def _generators_folder(client, subdir, token, include_release_subdir):
    # When installing a subfolder conanfile, cmake_layout places build folder inside that subfolder
    base = os.path.join(client.current_folder, subdir, "build", token)
    if include_release_subdir:
        return os.path.join(base, "Release", "generators")
    else:
        return os.path.join(base, "generators")
